        path = cwd.rstrip('/') + '/' + path
    components = deque(path.split('/'))
    current = '/'
    link_count = 0

    while components:
        comp = components.popleft()
        if comp == '' or comp == '.':
            continue
        if comp == '..':
            if current != '/':
                idx = current.rfind('/')
                if idx <= 0:
